 const groups=st.cats.map(c=>{const ls=lines.filter(l=>l.cat===c.id);return {...c,qty:ls.reduce((n,l)=>n+l.qty,0),value:ls.reduce((n,l)=>n+l.qty*l.price,0)};}).sort((a,b)=>b.value-a.value),gmx=Math.max(1,...groups.map(g=>g.value));
